const copy=x=>JSON.parse(JSON.stringify(x));
const canonical=x=>x===null||typeof x!=='object'?JSON.stringify(x):Array.isArray(x)?'['+x.map(canonical).join(',')+']':'{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}';
function freeze(x){if(x&&typeof x==='object'&&!Object.isFrozen(x)){Object.values(x).forEach(freeze);Object.freeze(x)}return x}
function fail(code,message){const e=new Error(message);e.code=code;throw e}
function schema(value,s,path='payload'){
 if(s.enum&&!s.enum.includes(value))fail('422',path+': invalid enum');
 if(s.type){const types=Array.isArray(s.type)?s.type:[s.type];const type=value===null?'null':Array.isArray(value)?'array':typeof value;
 if(!types.includes(type)&&!(types.includes('integer')&&Number.isInteger(value)))fail('422',path+': invalid type')}
 if(typeof value==='string'){if(s.minLength&&value.length<s.minLength||s.maxLength&&value.length>s.maxLength||s.pattern&&!new RegExp(s.pattern).test(value))fail('422',path+': invalid string')}
 if(typeof value==='number'&&(!Number.isFinite(value)||s.minimum!==undefined&&value<s.minimum||s.maximum!==undefined&&value>s.maximum))fail('422',path+': invalid number');
 if(Array.isArray(value)){if(s.minItems&&value.length<s.minItems||s.maxItems&&value.length>s.maxItems)fail('422',path+': invalid item count');if(s.items)value.forEach((v,i)=>schema(v,s.items,path+'['+i+']'))}
 else if(value&&typeof value==='object'){for(const k of s.required||[])if(!(k in value))fail('422',path+'.'+k+': required');for(const [k,v]of Object.entries(value)){if(['__proto__','constructor','prototype'].includes(k))fail('422','Unsafe key');if(s.properties?.[k])schema(v,s.properties[k],path+'.'+k);else if(s.additionalProperties===false)fail('422',path+'.'+k+': unknown');else if(typeof s.additionalProperties==='object')schema(v,s.additionalProperties,path+'.'+k)}}return true
}
function validateRelation(nodes,from,to,type){
 const a=nodes[from],b=nodes[to];if(!a||!b)fail('422','Endpoint does not belong to the current Enterprise revision');if(from===to)fail('422','Self relationship is invalid for this relation type');
 const rules={PROTECTED_BY:()=>b.type==='Security Control',DEPENDS_ON:()=>a.source!=='Simulation-local'&&b.source!=='Simulation-local',AUTHENTICATES_WITH:()=>b.type==='Identity Service',SENDS_LOGS:()=>b.type==='Monitoring Service',CONNECTS_TO:()=>a.interfaces?.some(x=>x.type==='ethernet')&&b.interfaces?.some(x=>x.type==='ethernet')};
 if(!rules[type]||!rules[type]())fail('422','Incompatible endpoint types for '+type);return {from:a.id,to:b.id,type,scope:a.source==='Simulation-local'||b.source==='Simulation-local'?'TWIN_OVERLAY':'ENTERPRISE_DRAFT'}
}
function validateTasks(tasks,edges){const ids=new Set(tasks.map(t=>t.id)),errors=[];if(ids.size!==tasks.length)errors.push('Duplicate task identity');
 for(const t of tasks)if(!t.title?.trim()||!t.validation||t.validation==='UNBOUND'||!t.signal||t.signal.includes('UNBOUND'))errors.push(t.id+': task title, validation and expected signal are required');
 for(const e of edges)if(!ids.has(e.from)||!ids.has(e.to)||e.from===e.to)errors.push(e.from+' → '+e.to+': invalid dependency');
 const visiting=new Set(),done=new Set();function visit(id){if(visiting.has(id)){errors.push(id+': dependency cycle');return}if(done.has(id))return;visiting.add(id);edges.filter(e=>e.from===id).forEach(e=>visit(e.to));visiting.delete(id);done.add(id)}ids.forEach(visit);return [...new Set(errors)]}
function validateScenario(phases,contract,available,labResolver){const errors=[],ids=new Set();if(!phases.length)errors.push('At least one phase is required');for(const p of phases){if(ids.has(p.id))errors.push(p.id+': duplicate identity');ids.add(p.id);if(!p.name.trim())errors.push(p.id+': name required');for(const e of p.elements){if(ids.has(e.id))errors.push(e.id+': duplicate identity');ids.add(e.id);if(!e.title?.trim())errors.push(e.id+': title required');if(e.kind==='lab'){if(!e.labRef?.revision||!e.labRef?.id||e.labRef.id==='UNRESOLVED')errors.push(e.id+': exact Lab revision required');else if(labResolver&&!labResolver(e.labRef))errors.push(e.id+': exact Lab revision unavailable')}if(e.kind==='decision'&&!e.condition)errors.push(e.id+': decision condition required')}}for(const cap of contract.capabilities||[])if(!available.includes(cap))errors.push('environment.capabilities.'+cap+': missing');return errors}
function preflight(checks,inputDigest,providerEpoch,now,ttl=60000){return {id:'PREFLIGHT-LOCAL',inputDigest,providerEpoch,observedAt:now,expiresAt:now+ttl,status:checks.some(x=>x.status==='BLOCKED')?'BLOCKED':'READY',checks:copy(checks)}}
function requestRun(run,action,ctx){const next={start:['READY','STARTING'],pause:['RUNNING','PAUSE_REQUESTED'],resume:['PAUSED','RESUME_REQUESTED'],stop:[['RUNNING','PAUSED'],'STOP_REQUESTED']};const rule=next[action];if(!rule)fail('422','Unknown runtime operation');if(![].concat(rule[0]).includes(run.lifecycle))fail('409','Operation does not match current lifecycle');if(run.pending)fail('409','Pending request must be reconciled first');if(!ctx.supported||ctx.connection!=='CONNECTED')fail('PLATFORM_GATED','Provider/session capability unavailable');if(action==='start'&&(!ctx.preflight||ctx.preflight.status!=='READY'||ctx.preflight.expiresAt<=ctx.now||ctx.preflight.inputDigest!==ctx.inputDigest||ctx.preflight.providerEpoch!==ctx.providerEpoch))fail('409','Preflight is blocked, expired or belongs to another input/provider epoch');return {...run,lifecycle:rule[1],pending:{action,invocationId:ctx.invocationId,providerEpoch:ctx.providerEpoch,from:run.lifecycle,stage:'REQUESTED'},version:run.version+1}}
function acknowledgeRun(run,receipt){if(!run.pending||receipt.invocationId!==run.pending.invocationId||receipt.providerEpoch!==run.pending.providerEpoch)fail('409','Stale or unrelated provider receipt');if(!receipt.accepted)return {...run,lifecycle:run.pending.from,pending:null,lastReceipt:'REJECTED',version:run.version+1};return {...run,pending:{...run.pending,stage:'ACKNOWLEDGED'},lastReceipt:'ACKNOWLEDGED',version:run.version+1}}
function completeRun(run,receipt){if(run.pending?.stage!=='ACKNOWLEDGED')fail('409','Completion requires an acknowledged request');if(receipt.invocationId!==run.pending.invocationId||receipt.providerEpoch!==run.pending.providerEpoch)fail('409','Completion receipt mismatch');const target={start:'RUNNING',pause:'PAUSED',resume:'RUNNING',stop:'STOPPED'}[run.pending.action];return {...run,lifecycle:target,pending:null,lastReceipt:'COMPLETED',version:run.version+1}}
function resultProjection(value){const clean=copy(value);delete clean.digest;delete clean.revisionDigest;return clean}
function sealedHandoffProjection(value){const clean=resultProjection(value);delete clean.sourceDigest;return clean}
function seal(run,events,reconciled,gaps,prior){if(!['STOPPED','COMPLETED','FAILED'].includes(run.lifecycle)||run.pending)fail('409','Run has not reached a confirmed terminal state');if(!reconciled)fail('409','Reconcile output high-watermarks before sealing');if(prior)return prior;return freeze({id:run.id.replace('RUN','RESULT'),revision:'r1',runId:run.id,runVersion:run.version,outcome:run.lifecycle,completeness:gaps.length?'SEALED_PARTIAL':'SEALED_COMPLETE',events:copy(events),gaps:copy(gaps)})}
function replay(events,index,delta,gaps=[]){if(!events.length)return {index:0,state:'EMPTY',event:null};const target=Math.max(0,Math.min(events.length-1,index+delta));const from=events[Math.max(0,Math.min(events.length-1,index))].seq,to=events[target].seq;const gap=gaps.find(g=>g.from<=Math.max(from,to)&&g.to>=Math.min(from,to)&&from!==to);return {index:target,state:gap?'RECORDED_GAP':'PAUSED',event:events[target],gap:gap||null}}
function annotate(store,expected,note,ref){if(expected!==store.version)fail('409','AAR revision conflict; keep the working annotation');if(!note.trim())fail('422','Annotation text is required');return {...store,version:store.version+1,notes:[...store.notes,{id:'AAR-NOTE-'+(store.notes.length+1),text:note,source:copy(ref),kind:'ANALYSIS'}]}}
function compare(left,right){if(!left||!right)return {status:!left?'MISSING_LEFT':'MISSING_RIGHT'};if(left.schema!==right.schema)return {status:'INCOMPATIBLE',reason:'Different result schemas'};return {status:'EXACT',left:copy(left.ref),right:copy(right.ref),scoreDelta:left.score==null||right.score==null?null:right.score-left.score}}
function effectiveLayout(preferred,width,focus,overlay){const wide=width>=1200,medium=width>=900;return {band:wide?'wide':medium?'medium':'narrow',left:focus?'hidden':wide?(preferred.left||'open'):medium?(preferred.left==='open'?'open':preferred.left):overlay==='left'?'overlay':'hidden',right:focus?'hidden':wide?(preferred.right||'open'):overlay==='right'?'overlay':'hidden',bottom:focus?'hidden':preferred.bottom}}
function moveRepresentation(positions,ids,dx,dy,snap=0){const next=copy(positions);for(const id of ids){const p=next[id];if(!p)continue;const round=n=>snap?Math.round(n/snap)*snap:n;p.x=round(p.x+dx);p.y=round(p.y+dy)}return next}
function remap(bindings,chord,command){if(!/^(?:Alt\+Shift\+[A-Z0-9]|Control\+Shift\+[A-Z0-9])$/.test(chord))fail('422','Use Alt+Shift+letter or Control+Shift+letter');if(bindings[chord]&&bindings[chord]!==command)fail('409','Shortcut collision with '+bindings[chord]);return {...bindings,[chord]:command}}

